/// org-chart: Teams loaded on demand and moving people
private struct OrgChartExample1: View {
    @State private var people = [
        MonarchOrgChartNode(id: "ana", name: "Ana Silva", title: "Chief executive"),
        MonarchOrgChartNode(id: "jo", parentID: "ana", name: "Jo Park", title: "Head of engineering", childCount: 2),
        MonarchOrgChartNode(id: "sam", parentID: "ana", name: "Sam Lee", title: "Head of finance"),
    ]

    var body: some View {
        MonarchOrgChart(
            people,
            layout: .list,
            onLoadChildren: { manager in
                people.append(MonarchOrgChartNode(id: "ola", parentID: manager.id, name: "Ola Berg"))
                people.append(MonarchOrgChartNode(id: "kai", parentID: manager.id, name: "Kai Moss"))
            },
            onMoveRequest: { person, target in
                guard let index = people.firstIndex(where: { $0.id == person.id }) else { return }
                switch target {
                case .manager(let id): people[index].parentID = id
                case .topLevel: people[index].parentID = nil
                case .unspecified: break
                }
            }
        )
        .frame(height: 420)
    }
}

